import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { bytesToHex, hexToBytes, encodeOp, signOp, signingHash, minFee, minTransferFee, signTransfer, type Op, type TxFields } from '../src/lib/lokyx.ts';

// Generated by the Rust node: `cargo run --example vectors > testdata/vectors.json`
const v = JSON.parse(readFileSync(new URL('../../testdata/vectors.json', import.meta.url), 'utf8'));

const h = (x: string) => hexToBytes(x);
const settings = (s: any) => ({
  recovery: s.recovery, safe: s.safe, delay: BigInt(s.delay), allowance: BigInt(s.allowance),
  heir: s.heir ? { address: s.heir.address, inactiveBlocks: BigInt(s.heir.inactiveBlocks) } : null,
});

/** The op of a vector case, as the library's Op. */
function opOf(o: any): Op {
  switch (o.kind) {
    case 'transfer': return { kind: 'transfer', to: o.to, value: BigInt(o.value) };
    case 'batch': return { kind: 'batch', payments: o.payments.map((p: any) => ({ to: p.to, amount: BigInt(p.amount) })) };
    case 'swapLock': return { kind: 'swapLock', amount: BigInt(o.amount), hashlock: h(o.hashlock), recipient: o.recipient, refundHeight: BigInt(o.refundHeight) };
    case 'swapClaim': return { kind: 'swapClaim', lock: h(o.lock), secret: h(o.secret) };
    case 'swapRefund': return { kind: 'swapRefund', lock: h(o.lock) };
    case 'vaultCreate': return { kind: 'vaultCreate', settings: settings(o.settings) };
    case 'vaultUpdate': return { kind: 'vaultUpdate', settings: settings(o.settings) };
    case 'vaultWithdraw': return { kind: 'vaultWithdraw', to: o.to, amount: BigInt(o.amount) };
    case 'vaultClose': return { kind: 'vaultClose' };
    case 'vaultCancel': return { kind: 'vaultCancel', id: h(o.id) };
    case 'vaultSweep': return { kind: 'vaultSweep', vault: o.vault };
    case 'vaultHeirClaim': return { kind: 'vaultHeirClaim', vault: o.vault };
    case 'keyCommitPq': return { kind: 'keyCommitPq', hash: h(o.hash) };
    case 'keyRotate': return { kind: 'keyRotate', newKey: o.newKey };
    case 'keyCancelRotate': return { kind: 'keyCancelRotate', account: o.account };
    case 'timelockLock': return { kind: 'timelockLock', beneficiary: o.beneficiary, amount: BigInt(o.amount), unlockHeight: BigInt(o.unlockHeight) };
    case 'timelockClaim': return { kind: 'timelockClaim', id: h(o.id) };
    case 'tokenCreate': return { kind: 'tokenCreate', symbol: o.symbol, name: o.name, decimals: o.decimals, supply: BigInt(o.supply) };
    case 'tokenTransfer': return { kind: 'tokenTransfer', token: h(o.token), to: o.to, amount: BigInt(o.amount) };
    case 'tokenBurn': return { kind: 'tokenBurn', token: h(o.token), amount: BigInt(o.amount) };
    case 'deploy': return { kind: 'deploy', value: BigInt(o.value), code: h(o.code), abi: o.abi, input: h(o.input), gas: BigInt(o.gas) };
    case 'call': return { kind: 'call', to: o.to, value: BigInt(o.value), input: h(o.input), gas: BigInt(o.gas) };
  }
  throw new Error(`unknown vector op ${o.kind}`);
}

const fieldsOf = (t: any): TxFields & { from: string; fee: bigint } => ({
  chainId: BigInt(t.chainId), from: t.from, nonce: BigInt(t.nonce), expires: BigInt(t.expires),
  memo: h(t.memo), fee: BigInt(t.fee),
});


for (const c of v.cases) {
  test(`signs an identical ${c.name}`, () => {
    const sk = h(v.keys[c.key].privateKey);
    const f = fieldsOf(c.tx);
    const op = opOf(c.tx.op);
    assert.equal(bytesToHex(encodeOp(op)), c.tx.opBytes);
    assert.equal(bytesToHex(signingHash(f, op)), c.signingHash);
    const s = signOp(op, f, sk);
    assert.equal(bytesToHex(s.bytes), c.signed);
    assert.equal(s.hash, c.hash);
  });
}

test('the minimum fee is the signed size times the per-byte price, plus gas', () => {
  for (const c of v.cases) {
    if (c.name.startsWith('transfer with memo')) continue; // pays more than the minimum on purpose
    assert.equal(minFee({ ...fieldsOf(c.tx), fee: undefined }, opOf(c.tx.op)).toString(), c.tx.fee);
  }
  assert.equal(minTransferFee().toString(), v.cases[0].tx.fee);
});

test('a plain transfer from the convenience function matches', () => {
  const c = v.cases[0];
  const s = signTransfer({ chainId: BigInt(v.chainId), nonce: 0n, to: c.tx.op.to, value: BigInt(c.tx.op.value) }, h(v.keys[0].privateKey));
  assert.equal(bytesToHex(s.bytes), c.signed);
});

test('every operation the library can build has a vector from the node', () => {
  const have = new Set(v.cases.map((c: any) => c.tx.op.kind));
  const source = readFileSync(new URL('../src/lib/lokyx.ts', import.meta.url), 'utf8');
  const union = source.slice(source.indexOf('export type Op ='), source.indexOf('export type Op =') + 2500);
  const kinds = [...union.matchAll(/\{ kind: '(\w+)'/g)].map((m) => m[1]).slice(0, 22);
  assert.ok(kinds.length >= 22);
  for (const k of kinds) assert.ok(have.has(k), `no vector for ${k}`);
});

test('the signature is the versioned enum: tag 0 then 64 bytes and the recovery id', () => {
  const c = v.cases[0];
  const bytes = h(c.signed);
  const opAndHeader = h(c.tx.opBytes).length;
  assert.equal(bytes[bytes.length - 66], 0); // Sig::Secp256k1Recoverable
  assert.equal(bytes.length - 66, bytes.length - 66);
  assert.ok(opAndHeader > 0);
});
